package com.powercms.cms.delivery;
import com.powercms.cms.content.entity.*;import com.powercms.cms.content.repo.*;import com.powercms.cms.delivery.navigation.*;import com.powercms.cms.model.repo.ContentTypeRepository;import com.powercms.cms.site.repo.SiteRepository;import freemarker.template.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.stereotype.Service;import java.time.*;import java.util.*;
/** The only factory for values exposed to FreeMarker. It deliberately never returns entities, repositories or servlet objects. */
@Service public class RenderContextFactory {
 private static final int MAX_DEPTH=8,MAX_COLLECTION=200,MAX_STRING=16384;private final SiteRepository sites;private final CategoryRepository categories;private final ContentItemRepository items;private final ContentVersionRepository versions;private final ContentTypeRepository types;private final NavTreeBuilder nav;private final NavBreadcrumbBuilder crumbs;private final UrlRewriteService urls;private final String environment;
 public record Input(UUID siteId,ContentItemEntity item,Map<String,Object> contentModel,boolean preview,String method,String path,Map<String,?> query,Locale locale,String username,Instant renderInstant,Map<String,Object> pagination){}
 public RenderContextFactory(SiteRepository s,CategoryRepository c,ContentItemRepository i,ContentVersionRepository v,ContentTypeRepository t,NavTreeBuilder n,NavBreadcrumbBuilder b,UrlRewriteService u,@Value("${spring.profiles.active:default}")String env){sites=s;categories=c;items=i;versions=v;types=t;nav=n;crumbs=b;urls=u;environment=env;}
 public Map<String,Object> create(Input in){var site=sites.findById(in.siteId()).orElseThrow();Locale locale=in.locale()!=null?in.locale():Locale.forLanguageTag(site.getDefaultLocale());String route=in.item()==null?safePath(in.path()):in.item().getRoutePath();Map<String,Object> siteDto=Map.of("id",site.getId().toString(),"key",site.getSiteKey(),"name",site.getName(),"defaultLocale",site.getDefaultLocale(),"timezone",site.getTimezone(),"status",site.getStatus());Map<String,Object> request=Map.of("method",safeMethod(in.method()),"path",safePath(in.path()==null?route:in.path()),"query",sanitize(in.query()==null?Map.of():in.query(),0));Map<String,Object> page=in.item()==null?Map.of():Map.of("id",in.item().getId().toString(),"title",in.item().getTitle(),"routePath",String.valueOf(in.item().getRoutePath()),"status",in.item().getStatus());Map<String,Object> category=category(in);Map<String,Object> model=new LinkedHashMap<>();model.put("contentModel",sanitize(in.contentModel()==null?Map.of():in.contentModel(),0));model.put("content",model.get("contentModel"));model.put("site",siteDto);model.put("siteConfig",siteDto);model.put("request",request);model.put("requestParameters",request.get("query"));model.put("cookies",Map.of());model.put("session",Map.of());model.put("locale",locale.toLanguageTag());model.put("language",locale.getLanguage());model.put("currentUser",Map.of("authenticated",in.username()!=null&&!in.username().isBlank(),"name",in.username()==null?"anonymous":clip(in.username())));model.put("category",category);model.put("currentPage",page);model.put("page",page);model.put("route",Map.of("path",route==null?"/":route));model.put("url",route==null?"/":route);model.put("now",(in.renderInstant()==null?Instant.now():in.renderInstant()).toString());model.put("pagination",sanitize(in.pagination()==null?Map.of():in.pagination(),0));model.put("flags",Map.of("preview",in.preview(),"environment",environment));model.put("modePreview",in.preview());model.put("crafterEnv",environment);model.put("globalProperties",Map.of("environment",environment));model.put("siteContext",null);model.put("application",null);model.put("applicationContext",null);model.put("siteItemService",new SiteItemMethod(in.siteId()));model.put("urlTransformationService",new UrlMethod(in.siteId(),in.preview()));model.put("navTreeBuilder",new NavMethod(in.siteId(),in.preview()));model.put("navBreadcrumbBuilder",new BreadcrumbMethod(route));model.put("renderBreadcrumb",new BreadcrumbMethod(route));model.put("navigation",new NavMethod(in.siteId(),in.preview()));return Collections.unmodifiableMap(model);}
 private Map<String,Object> category(Input in){if(in.item()==null||in.item().getCategoryId()==null)return Map.of();return categories.findById(in.item().getCategoryId()).filter(x->in.siteId().equals(x.getSiteId())).map(x->Map.<String,Object>of("id",x.getId().toString(),"name",x.getName(),"pathAlias",String.valueOf(x.getPathAlias()),"depth",x.getDepth())).orElse(Map.of());}
 private Object sanitize(Object value,int depth){if(value==null||value instanceof String||value instanceof Number||value instanceof Boolean||value instanceof UUID||value instanceof Instant)return value instanceof String s?clip(s):value;if(depth>=MAX_DEPTH)return null;if(value instanceof Map<?,?> m){Map<String,Object> out=new LinkedHashMap<>();for(var e:m.entrySet()){if(out.size()>=MAX_COLLECTION)break;String k=clip(String.valueOf(e.getKey()));Object v=sanitize(e.getValue(),depth+1);if(v!=null)out.put(k,v);}return Collections.unmodifiableMap(out);}if(value instanceof Collection<?> c){List<Object> out=new ArrayList<>();for(Object x:c){if(out.size()>=MAX_COLLECTION)break;Object v=sanitize(x,depth+1);if(v!=null)out.add(v);}return List.copyOf(out);}if(value.getClass().isArray()){List<Object> out=new ArrayList<>();int n=Math.min(java.lang.reflect.Array.getLength(value),MAX_COLLECTION);for(int i=0;i<n;i++){Object v=sanitize(java.lang.reflect.Array.get(value,i),depth+1);if(v!=null)out.add(v);}return List.copyOf(out);}return clip(String.valueOf(value));}
 private String clip(String s){return s==null?"":s.substring(0,Math.min(s.length(),MAX_STRING));}private String safeMethod(String m){return m==null?"GET":Set.of("GET","POST","HEAD","PUT","DELETE","PATCH").contains(m.toUpperCase(Locale.ROOT))?m.toUpperCase(Locale.ROOT):"OTHER";}private String safePath(String p){if(p==null||p.isBlank())return "/";String x=clip(p);return x.startsWith("/")&&!x.contains("..")&&!x.contains("\\")?x:"/";}
 private final class SiteItemMethod implements TemplateMethodModelEx{private final UUID site;SiteItemMethod(UUID s){site=s;}public Object exec(List args)throws TemplateModelException{if(args==null||args.size()!=1)throw new TemplateModelException("siteItemService requires one route");String path=String.valueOf(freemarker.template.utility.DeepUnwrap.unwrap((TemplateModel)args.get(0)));return items.findBySiteIdAndRoutePathAndStatus(site,path,ContentItemEntity.STATUS_PUBLISHED).map(x->{Map<String,Object> out=new LinkedHashMap<>();out.put("id",x.getId().toString());out.put("title",x.getTitle());out.put("routePath",x.getRoutePath());Integer v=x.getPublishedVersion();if(v!=null)versions.findByContentItemIdAndVersion(x.getId(),v).ifPresent(cv->{try{out.put("fields",sanitize(new com.fasterxml.jackson.databind.ObjectMapper().readValue(cv.getFieldValues(),Map.class),0));}catch(Exception ignored){out.put("fields",Map.of());}});return Collections.unmodifiableMap(out);}).orElse(Map.of());}}
 private final class UrlMethod implements TemplateMethodModelEx{private final UUID site;private final boolean preview;UrlMethod(UUID s,boolean p){site=s;preview=p;}public Object exec(List args)throws TemplateModelException{if(args==null||args.size()!=1)throw new TemplateModelException("urlTransformationService requires one path");return urls.rewrite(site,String.valueOf(freemarker.template.utility.DeepUnwrap.unwrap((TemplateModel)args.get(0))),preview);}}
 private final class NavMethod implements TemplateMethodModelEx{private final UUID site;private final boolean preview;NavMethod(UUID s,boolean p){site=s;preview=p;}public Object exec(List args)throws TemplateModelException{if(args!=null&&args.size()>2)throw new TemplateModelException("navTreeBuilder accepts depth and filter only");int depth=3;Map<String,Object> f=Map.of();if(args!=null&&!args.isEmpty())depth=Integer.parseInt(String.valueOf(freemarker.template.utility.DeepUnwrap.unwrap((TemplateModel)args.get(0))));if(args!=null&&args.size()==2){Object raw=freemarker.template.utility.DeepUnwrap.unwrap((TemplateModel)args.get(1));if(!(raw instanceof Map<?,?> m))throw new TemplateModelException("filter must be a map");Map<String,Object> copy=new LinkedHashMap<>();m.forEach((k,v)->copy.put(String.valueOf(k),v));f=copy;}Set<String> allowed=Set.of("contentType","status","pathPrefix","titlePrefix","excludeIds");if(!allowed.containsAll(f.keySet()))throw new TemplateModelException("filter contains unsupported fields");Set<UUID> ids=new HashSet<>();Object rawIds=f.get("excludeIds");if(rawIds instanceof Collection<?> c)for(Object x:c)if(ids.size()<100)try{ids.add(UUID.fromString(String.valueOf(x)));}catch(Exception ignored){}return nav.build(site,depth,new NavTreeBuilder.Filter(text(f,"contentType"),text(f,"status"),text(f,"pathPrefix"),text(f,"titlePrefix"),ids),preview);}private String text(Map<String,Object>m,String k){return m.get(k)==null?null:String.valueOf(m.get(k));}}
 private final class BreadcrumbMethod implements TemplateMethodModelEx{private final String route;BreadcrumbMethod(String r){route=r;}public Object exec(List args)throws TemplateModelException{if(args!=null&&args.size()>1)throw new TemplateModelException("breadcrumb accepts at most one path");String p=route;if(args!=null&&!args.isEmpty())p=String.valueOf(freemarker.template.utility.DeepUnwrap.unwrap((TemplateModel)args.get(0)));return crumbs.build(p);}}
}
